/**
 * Commerce OS — Embedded PostgreSQL (no install required)
 *
 * Runs a REAL PostgreSQL (17 wire protocol) in-process using PGlite (WASM build
 * shipped with Prisma tooling) exposed over TCP via @electric-sql/pglite-socket.
 * - Data directory: .pgdata/ (persistent, gitignored)
 * - Schema: applied once from apps/api/prisma/embedded-init.sql (generated by
 *   `prisma migrate diff --from-empty --to-schema prisma/schema.prisma --script`)
 * - Port: 127.0.0.1:5432 — same as the docker-compose dev database, so
 *   DATABASE_URL needs no changes.
 *
 * Usage:  node scripts/embedded-postgres.mjs
 * Stop:   Ctrl+C (graceful)
 */

import { PGlite } from "@electric-sql/pglite";
import { PGLiteSocketServer } from "@electric-sql/pglite-socket";
import { existsSync, mkdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dataDir = path.join(rootDir, ".pgdata");
const ddlPath = path.join(rootDir, "apps", "api", "prisma", "embedded-init.sql");

if (!existsSync(dataDir)) {
  mkdirSync(dataDir, { recursive: true });
  console.log(`📁 Created data directory: ${dataDir}`);
}

console.log("🟡 Starting embedded PostgreSQL (PGlite WASM)…");
const db = new PGlite(dataDir);

// Apply the schema once (idempotent — checks for the tenants table)
const probe = await db.query(`SELECT to_regclass('public.tenants') AS t`);
if (!probe.rows[0]?.t) {
  const ddl = readFileSync(ddlPath, "utf8");
  console.log("📄 Applying schema (embedded-init.sql)…");
  await db.exec(ddl);
  console.log("✅ Schema applied (all enums, tables, indexes)");
} else {
  console.log("ℹ️ Schema already present — skipping DDL");
}

const server = new PGLiteSocketServer({
  db,
  host: "127.0.0.1",
  port: Number(process.env.PG_EMBEDDED_PORT ?? 5432),
  // Prisma pool + seed + worker connect concurrently — queries are globally
  // queued inside PGlite, so multiple wire connections are safe for dev.
  maxConnections: 100,
  // PG_INSPECT=1 → hex-dump the wire exchange (wire-protocol debugging)
  inspect: process.env.PG_INSPECT === "1",
  debug: process.env.PG_INSPECT === "1",
});

await server.start();
console.log(`🟢 Embedded PostgreSQL ready on ${server.getServerConn()}`);
console.log("   (DATABASE_URL=localhost:5432 — same as docker-compose dev)");

let stopping = false;
async function shutdown() {
  if (stopping) return;
  stopping = true;
  console.log("\n🔻 Shutting down embedded PostgreSQL…");
  try {
    await server.stop();
    await db.close();
  } catch (err) {
    console.error("Shutdown warning:", err?.message ?? err);
  }
  process.exit(0);
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);
